 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    overall = counts.most_common(1)[0][0]
    n = h * w
    marker_colors = {
        color for color, count in counts.items()
        if color != overall and count <= max(2, n // 10)
    }
    if not marker_colors:
        return [[overall]]

    marker_rows = [r for r in range(h) if any(v in marker_colors for v in grid[r])]
    marker_cols = [c for c in range(w) if any(grid[r][c] in marker_colors for r in range(h))]
    if len(marker_rows) < 2 or len(marker_cols) < 2:
        return [[overall]]

    row_set, col_set = set(marker_rows), set(marker_cols)
    interior = Counter(
        grid[r][c]
        for r in range(h) if r not in row_set
        for c in range(w) if c not in col_set
    )
    for color in marker_colors:
        interior.pop(color, None)
    scaffold = interior.most_common(1)[0][0] if interior else overall

    junction = [[grid[r][c] for c in marker_cols] for r in marker_rows]
    out = []
    for i in range(len(marker_rows) - 1):
        row = []
        for j in range(len(marker_cols) - 1):
            corners = (junction[i][j], junction[i][j + 1],
                       junction[i + 1][j], junction[i + 1][j + 1])
            row.append(corners[0] if all(v == corners[0] for v in corners) else scaffold)
        out.append(row)
    return out


if __name__ == "__main__":
    pass
